DELIMITER //
CREATE PROCEDURE p_student_count(OUT p_total INT)
READS SQL DATA
BEGIN
  SELECT COUNT(*) INTO p_total FROM students;
END//
DELIMITER ;
CALL p_student_count(@total);
SELECT @total AS total;

CREATE FUNCTION f_score_label(p_score INT) RETURNS VARCHAR(12)
DETERMINISTIC NO SQL
RETURN IF(p_score IS NULL,'待录入',IF(p_score>=60,'通过','待补'));
SELECT f_score_label(72) AS a, f_score_label(NULL) AS b;

DELIMITER //
CREATE PROCEDURE p_next_value(IN p_input INT,OUT p_result INT)
CONTAINS SQL
BEGIN
  DECLARE v_next INT DEFAULT 0;
  SET v_next=p_input+1;
  SET p_result=v_next;
END//
DELIMITER ;
CALL p_next_value(4,@answer);
SELECT @answer AS answer;

DELIMITER //
CREATE PROCEDURE p_find_name(IN p_id INT,OUT p_name VARCHAR(64))
READS SQL DATA
BEGIN
  DECLARE v_missing BOOLEAN DEFAULT FALSE;
  DECLARE v_name VARCHAR(64);
  DECLARE no_row CONDITION FOR SQLSTATE '02000';
  DECLARE CONTINUE HANDLER FOR no_row SET v_missing=TRUE;
  SELECT name INTO v_name FROM students WHERE id=p_id;
  IF v_missing THEN SET p_name='未找到'; ELSE SET p_name=v_name; END IF;
END//
DELIMITER ;
CALL p_find_name(-1,@found_name);
SELECT @found_name AS result_name;

DELIMITER //
CREATE PROCEDURE p_cursor_total(OUT p_total INT)
READS SQL DATA
BEGIN
  DECLARE v_done BOOLEAN DEFAULT FALSE;
  DECLARE v_score INT;
  DECLARE cur CURSOR FOR SELECT score FROM students WHERE score IS NOT NULL;
  DECLARE CONTINUE HANDLER FOR NOT FOUND SET v_done=TRUE;
  SET p_total=0;
  OPEN cur;
  read_loop: LOOP
    FETCH cur INTO v_score;
    IF v_done THEN LEAVE read_loop; END IF;
    SET p_total=p_total+v_score;
  END LOOP;
  CLOSE cur;
END//
DELIMITER ;
CALL p_cursor_total(@score_total);
SELECT @score_total AS total;

DELIMITER //
CREATE PROCEDURE p_sum_to(IN p_n INT,OUT p_sum INT)
CONTAINS SQL
BEGIN
  DECLARE v_i INT;
  SET v_i=p_n;
  SET p_sum=0;
  WHILE v_i>0 DO
    SET p_sum=p_sum+v_i;
    SET v_i=v_i-1;
  END WHILE;
END//
DELIMITER ;
CALL p_sum_to(3,@sum_value);
SELECT @sum_value AS total;

SET PERSIST max_connections=200;
SELECT @@GLOBAL.max_connections AS current_limit;
RESET PERSIST IF EXISTS max_connections;

DELIMITER //
CREATE PROCEDURE p_total_demo(IN p_n INT,OUT p_total INT)
CONTAINS SQL
BEGIN
  DECLARE v_i INT DEFAULT 0;
  SET p_total=0;
  WHILE v_i<p_n DO
    SET v_i=v_i+1;
    SET p_total=p_total+v_i;
  END WHILE;
END//
DELIMITER ;
CALL p_total_demo(3,@demo_total);
SELECT @demo_total AS total;
